class Solution {
public:
    string mergeCharacters(string s, int k) {
        while (true) {
            bool changed = false;
            for (int i = 0; i < (int)s.size() && !changed; ++i) {
                for (int j = i + 1; j < (int)s.size() && j - i <= k; ++j) {
                    if (s[i] == s[j]) {
                        s.erase(j, 1);
                        changed = true;
                        break;
                    }
                }
            }
            if (!changed) return s;
        }
    }
};
